const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const NL = String.fromCharCode(10);
const bin = "/tmp/fakebin";
const proj = "/tmp/proj";
const marker = "/tmp/ran.txt";
fs.mkdirSync(bin, { recursive: true });
fs.mkdirSync(proj, { recursive: true });
try { fs.unlinkSync(marker); } catch {}
for (const name of ["npm", "nub"]) {
  const p = path.join(bin, name);
  fs.writeFileSync(p, ["#!/bin/sh", 'if [ "$1" = --version ]; then echo 1.0.0; exit 0; fi', "echo " + name + ' "$@" > ' + marker, "exit 0", ""].join(NL));
  fs.chmodSync(p, 0o755);
}
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "init", "demo", "--yes"], {
  cwd: proj,
  encoding: "utf8",
  timeout: 70000,
  env: { ...process.env, PATH: bin + ":" + process.env.PATH, HOME: "/tmp", npm_config_user_agent: "nub/0.4.5 npm/? node/v24.0.0 linux x64", WRANGLER_SEND_METRICS: "false", CI: "true" },
});
if (r.error) broken("wrangler init did not run: " + r.error.message);
if (!fs.existsSync(marker)) broken("no package manager was invoked; exit " + r.status + ": " + (String(r.stdout) + String(r.stderr)).slice(-400));
const ran = fs.readFileSync(marker, "utf8").trim();
if (/^npm /.test(ran)) symptom("with a nub npm_config_user_agent and a nub binary, wrangler init ran npm instead of nub: " + ran);
if (!/^nub create cloudflare/.test(ran)) broken("unexpected command: " + ran);
console.log("OK: wrangler init ran " + ran);

